package com.portfolio.student;
import java.sql.*;import java.util.*;
public class StudentRepository {private final String jdbcUrl;public StudentRepository(String jdbcUrl){this.jdbcUrl=jdbcUrl;}private Connection connect()throws SQLException{return DriverManager.getConnection(jdbcUrl);}public void initialize()throws SQLException{try(Connection c=connect();Statement s=c.createStatement()){s.execute("CREATE TABLE IF NOT EXISTS students(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL UNIQUE,course VARCHAR(120) NOT NULL)");}}public long add(String name,String email,String course)throws SQLException{try(Connection c=connect();PreparedStatement p=c.prepareStatement("INSERT INTO students(name,email,course) VALUES(?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,name);p.setString(2,email);p.setString(3,course);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();return r.getLong(1);}}}public List<String> findAll()throws SQLException{List<String> rows=new ArrayList<>();try(Connection c=connect();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT id,name,email,course FROM students ORDER BY id")){while(r.next())rows.add(r.getLong(1)+"|"+r.getString(2)+"|"+r.getString(3)+"|"+r.getString(4));}return rows;}public boolean delete(long id)throws SQLException{try(Connection c=connect();PreparedStatement p=c.prepareStatement("DELETE FROM students WHERE id=?")){p.setLong(1,id);return p.executeUpdate()==1;}}}